// trunk: a function table the test suite checks
function makeTrunk() { return { defs: { getUser: true }, calls: [] }; }

// PR-A: rename getUser -> loadUser (deletes getUser def, rewrites its own calls)
const prA = (t) => { delete t.defs.getUser; t.defs.loadUser = true; t.calls = t.calls.filter(c => c !== 'getUser'); t.calls.push('loadUser'); };
// PR-B: add a NEW call site to getUser (the old name)
const prB = (t) => { t.calls.push('getUser'); };

// test suite: every call site must resolve to a defined function
function suiteGreen(t) { return t.calls.every(c => t.defs[c] === true); }

function testAgainst(base, pr) { const t = structuredClone(base); pr(t); return suiteGreen(t); }

function prMerge() {
  const trunk = makeTrunk();
  const aGreen = testAgainst(trunk, prA); // vs original trunk
  const bGreen = testAgainst(trunk, prB); // vs SAME original trunk
  // both green -> both land
  const final = makeTrunk(); prA(final); prB(final);
  const trunkOk = suiteGreen(final);
  return { aGreen, bGreen, landed: ['A','B'], trunkOk };
}

function queueMerge() {
  let trunk = makeTrunk();
  const landed = [];
  // A enters first: test vs trunk
  if (testAgainst(trunk, prA)) { prA(trunk); landed.push('A'); }
  // B enters next: test vs trunk-PLUS-A (projected state)
  if (testAgainst(trunk, prB)) { prB(trunk); landed.push('B'); }
  return { landed, trunkOk: suiteGreen(trunk) };
}

const pre = prMerge();
const q = queueMerge();
console.log('pre-merge gate: landed ' + pre.landed.join('+') + ', trunk green? ' + pre.trunkOk);
console.log('merge queue: landed ' + q.landed.join('+') + ', trunk green? ' + q.trunkOk);
console.log(pre.trunkOk ? 'no break' : 'CAUGHT BY: merge queue only');
